<?php
declare(strict_types=1);
namespace Medbiohim\Services;
final class ExcelScheduleImporter {
 public static function parse(string $path):array{if(!is_file($path))throw new \InvalidArgumentException('Excel file not found');$ext=strtolower(pathinfo($path,PATHINFO_EXTENSION));if($ext==='csv')return self::csv($path);if($ext!=='xlsx')throw new \InvalidArgumentException('Only .xlsx or .csv files are supported');if(!class_exists(\ZipArchive::class))throw new \RuntimeException('ZipArchive extension is required');$z=new \ZipArchive();if($z->open($path)!==true)throw new \RuntimeException('Could not open workbook');$shared=[];$sx=$z->getFromName('xl/sharedStrings.xml');if($sx!==false&&($x=@simplexml_load_string($sx))!==false)foreach($x->si as $si){$t='';foreach($si->xpath('.//t')?:[] as $v)$t.=(string)$v;$shared[]=$t;}$sheet=$z->getFromName('xl/worksheets/sheet1.xml');$z->close();if($sheet===false)throw new \RuntimeException('Worksheet not found');$x=@simplexml_load_string($sheet);if($x===false)throw new \RuntimeException('Invalid worksheet XML');$rows=[];foreach($x->sheetData->row as $row){$c=[];foreach($row->c as $cell){preg_match('/([A-Z]+)\d+/',(string)$cell['r'],$m);$i=self::col($m[1]??'A');$v=(string)($cell->v??'');if((string)$cell['t']==='s'&&isset($shared[(int)$v]))$v=$shared[(int)$v];$c[$i]=trim($v);}if($c)$rows[]=$c;}if(!$rows)return [];$h=self::headers(array_shift($rows));$out=[];foreach($rows as $c){$r=[];foreach($h as $i=>$k)if($k!=='')$r[$k]=$c[$i]??'';$n=self::row($r);if($n['date']!==''&&($n['subject']!==''||$n['title']!==''))$out[]=$n;}return $out;}
 private static function csv(string $p):array{$f=fopen($p,'rb');if(!$f)throw new \RuntimeException('Could not open CSV');$h=fgetcsv($f,0,';');if(!$h||count($h)<2){rewind($f);$h=fgetcsv($f,0,',');}$h=self::headers($h?:[]);$o=[];while(($c=fgetcsv($f,0,';'))!==false){$r=[];foreach($h as $i=>$k)if($k!=='')$r[$k]=$c[$i]??'';$n=self::row($r);if($n['date']!==''&&($n['subject']!==''||$n['title']!==''))$o[]=$n;}fclose($f);return $o;}
 private static function headers(array $h):array{$m=['дата'=>'date','день'=>'date','date'=>'date','предмет'=>'subject','дисциплина'=>'subject','subject'=>'subject','занятие'=>'title','тема'=>'title','название'=>'title','title'=>'title','тип'=>'type','вид'=>'type','type'=>'type','начало'=>'start_time','время начала'=>'start_time','start'=>'start_time','start_time'=>'start_time','конец'=>'end_time','время окончания'=>'end_time','end'=>'end_time','end_time'=>'end_time','аудитория'=>'room','кабинет'=>'room','room'=>'room','корпус'=>'building','building'=>'building','примечание'=>'notes','примечания'=>'notes','notes'=>'notes'];$o=[];foreach($h as $v){$k=preg_replace('/\s+/u',' ',mb_strtolower(trim((string)$v),'UTF-8'))??'';$o[]=$m[$k]??$k;}return $o;}
 private static function row(array $r):array{$t=mb_strtolower(trim((string)($r['type']??'other')),'UTF-8');$map=['лекция'=>'lecture','лек'=>'lecture','практика'=>'practice','практическое'=>'practice','лабораторная'=>'laboratory','лаба'=>'laboratory','семинар'=>'seminar','экзамен'=>'exam','зачет'=>'credit','зачёт'=>'credit'];return ['date'=>self::date((string)($r['date']??'')),'subject'=>trim((string)($r['subject']??'')),'title'=>trim((string)($r['title']??'')),'type'=>$map[$t]??(in_array($t,['lecture','practice','laboratory','seminar','exam','credit','consultation','other'],true)?$t:'other'),'start_time'=>trim((string)($r['start_time']??'')),'end_time'=>trim((string)($r['end_time']??'')),'room'=>trim((string)($r['room']??'')),'building'=>trim((string)($r['building']??'')),'notes'=>trim((string)($r['notes']??''))];}
 private static function date(string $v):string{$v=trim($v);if($v==='')return '';if(is_numeric($v)&&$v>20000&&$v<60000)return (new \DateTimeImmutable('1899-12-30'))->modify('+'.(int)$v.' days')->format('Y-m-d');foreach(['d.m.Y','d/m/Y','Y-m-d','d.m.y','d/m/y'] as $f){$d=\DateTimeImmutable::createFromFormat($f,$v);if($d instanceof \DateTimeImmutable)return $d->format('Y-m-d');}$t=strtotime($v);return $t!==false?date('Y-m-d',$t):$v;}
 private static function col(string $s):int{$n=0;foreach(str_split($s) as $c)$n=$n*26+ord($c)-64;return $n-1;}
}
